#include "stdafx.h"#include "RTMR.h"KRTMR::KRTMR(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "Local Preset",  "Remote",  "Use external preload",};BOOL KRTMR::OnParsingSingleText( std::string &szText, RECTL *rc ){  if( m_CurParameterID!=-1 )  {    AddParam( s_MyParameters[m_CurParameterID], szText.c_str() );    CStringA s;    if( !m_CurParameterID )      s.Format( "LocalPreset = %d", atoi(szText.c_str()) );    else if( 1==m_CurParameterID)      s.Format( "Remote = %d", atoi(szText.c_str()) );    else if( 2==m_CurParameterID)    {      s = szText.c_str();      if( !s.Compare("NO") )        s.Format( "UseExternalPreload = FALSE" );      else        s.Format( "UseExternalPreload = TRUE" );    }    if( !s.IsEmpty() )      m_settings.push_back( s.GetBuffer() );    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;//сделать преобразование параметра к виду, пригодному для формирования исполняемого кода  }  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      return TRUE;    }  }  return FALSE;}